import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BAr9kJgi.js";const p=JSON.parse('{"title":"ADR-0001：CesiumEntity 使用类型化 config 对象","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-cesium-entity-config-object.md","filePath":"adr/0001-cesium-entity-config-object.md","lastUpdated":1787623881000}'),c={name:"adr/0001-cesium-entity-config-object.md"};function d(l,e,n,r,s,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0001-cesiumentity-使用类型化-config-对象" tabindex="-1">ADR-0001：CesiumEntity 使用类型化 config 对象 <a class="header-anchor" href="#adr-0001-cesiumentity-使用类型化-config-对象" aria-label="Permalink to &quot;ADR-0001：CesiumEntity 使用类型化 config 对象&quot;">​</a></h1><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>已接受</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>原 API 将 <code>position</code>、<code>point</code>、<code>label</code>、<code>polyline</code> 和 <code>polygon</code> 全部平铺为组件属性，难以判断参数属于点、线还是面，也无法表达线和面标签需要独立位置。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>新增由 <code>type</code> 区分的 <code>CesiumEntityConfig</code>，通过 <code>&lt;CesiumEntity :config=&quot;config&quot; /&gt;</code> 传入。点和线直接使用自身坐标渲染，只对没有标签坐标的面计算中心；<code>placement</code> 用于设置标签偏向，也允许通过 <code>position</code> 覆盖自动位置。旧平铺属性继续兼容，新文档优先介绍 <code>config</code>。</p><p>业务配置中的颜色同时接受 CSS 字符串和 Cesium <code>Color</code>，标签绘制方式同时接受 <code>fill</code>、<code>outline</code>、<code>fill-and-outline</code> 和 Cesium <code>LabelStyle</code>，由组件在创建 Entity 前统一转换。</p><p>其它常用 Cesium 值同样在组件边界转换：<code>alwaysVisible</code>、数组形式的 <code>pixelOffset</code>、字符串形式的贴地与对齐方式，以及经纬度坐标数组。Cesium 原生对象只作为高级兼容输入，不作为主要文档写法。</p><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><h3 id="正面" tabindex="-1">正面 <a class="header-anchor" href="#正面" aria-label="Permalink to &quot;正面&quot;">​</a></h3><ul><li>一个实体的图形、标签和业务数据集中管理。</li><li>TypeScript 根据 <code>type</code> 提示正确配置，并检查线面标签位置。</li><li>旧项目可以无修改升级。</li></ul><h3 id="负面" tabindex="-1">负面 <a class="header-anchor" href="#负面" aria-label="Permalink to &quot;负面&quot;">​</a></h3><ul><li>组件内部需要保留一层新旧 API 归一化逻辑。</li><li>在下一个主版本移除旧 API 前，两种写法会同时存在。</li></ul><h2 id="备选方案" tabindex="-1">备选方案 <a class="header-anchor" href="#备选方案" aria-label="Permalink to &quot;备选方案&quot;">​</a></h2><ul><li>直接删除旧 Props：API 最简洁，但会破坏现有项目。</li><li>继续使用平铺 Props：实现成本最低，但无法解决文档和类型语义模糊的问题。</li></ul>',16)])])}const f=o(c,[["render",d]]);export{p as __pageData,f as default};
